import {spawnSync} from 'node:child_process';

// specs/lore-test-descriptors/spec.md#1
it('includes a stamped spec anchor in the test descriptor', () => {
  const source = "// specs/example/spec.md#2\nit('works', () => {});\n";
  const program = `import {descriptor} from './scripts/lore-descriptors.mjs';
    console.log(JSON.stringify(descriptor('src/example.test.ts', {fullName: 'works', location: {line: 2}}, ${JSON.stringify(source)})));`;
  const result = spawnSync(process.execPath, ['--input-type=module', '-e', program], {encoding: 'utf8'});
  expect(result.status).toBe(0);
  expect(JSON.parse(result.stdout)).toEqual({
    id: 'src/example.test.ts::works',
    name: 'works',
    file: 'src/example.test.ts',
    spec: 'specs/example/spec.md#2',
  });
});
export function descriptor(file, assertion, source) {
  const result = {id: `${file}::${assertion.fullName}`, name: assertion.fullName, file};
  const lines = source.split(/\r?\n/);
  const preceding = lines[assertion.location?.line - 2] ?? '';
  const anchor = preceding.match(/\b(specs\/[^\s]+\/spec\.md#\d+)\b/);
  if (anchor) result.spec = anchor[1];
  return result;
}
